use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Language\Text;use Joomla\CMS\Layout\LayoutHelper;use Joomla\CMS\Router\Route;use Joomla\Component\Genesisproductupdater\Administrator\Helper\ProductUpdaterHelper;
$this->getDocument()->getWebAssetManager()->useScript('table.columns')->useScript('multiselect');$user=$this->getCurrentUser();$listOrder=$this->escape($this->state->get('list.ordering'));$listDirn=$this->escape($this->state->get('list.direction'));
?>
<form action="<?php echo Route::_('index.php?option=com_genesisproductupdater&view=bundles'); ?>" method="post" name="adminForm" id="adminForm"><div id="j-main-container" class="j-main-container"><?php echo LayoutHelper::render('joomla.searchtools.default',['view'=>$this]); ?><?php if(empty($this->items)): ?><div class="alert alert-info"><?php echo Text::_('JGLOBAL_NO_MATCHING_RESULTS'); ?></div><?php else: ?><table class="table" id="bundleList"><thead><tr><td style="width:1%"><?php echo HTMLHelper::_('grid.checkall'); ?></td><th style="width:1%"><?php echo HTMLHelper::_('searchtools.sort','JSTATUS','a.state',$listDirn,$listOrder); ?></th><th><?php echo HTMLHelper::_('searchtools.sort','COM_GENESISPRODUCTUPDATER_FIELD_TITLE_LABEL','a.title',$listDirn,$listOrder); ?></th><th><?php echo Text::_('COM_GENESISPRODUCTUPDATER_FIELD_BUNDLE_PRODUCTS_LABEL'); ?></th><th><?php echo Text::_('COM_GENESISPRODUCTUPDATER_GENERATED_FILES'); ?></th><th style="width:6%"><?php echo HTMLHelper::_('searchtools.sort','JGRID_HEADING_ID','a.id',$listDirn,$listOrder); ?></th></tr></thead><tbody><?php foreach($this->items as $i=>$item): $canEdit=$user->authorise('core.edit','com_genesisproductupdater');$ids=json_decode((string)$item->product_ids,true)?:[];$info=ProductUpdaterHelper::getBundleFileInfo((array)$item); ?><tr><td><?php echo HTMLHelper::_('grid.id',$i,$item->id); ?></td><td><?php echo HTMLHelper::_('jgrid.published',$item->state,$i,'bundles.',$user->authorise('core.edit.state','com_genesisproductupdater'),'cb'); ?></td><th><?php if($canEdit): ?><a href="<?php echo Route::_('index.php?option=com_genesisproductupdater&task=bundle.edit&id='.(int)$item->id); ?>"><?php echo $this->escape($item->title); ?></a><?php else: echo $this->escape($item->title); endif; ?></th><td><?php echo count($ids); ?></td><td><a href="<?php echo $this->escape($info['url']); ?>" target="_blank"><?php echo $this->escape($info['subpath']); ?></a> <?php echo $info['exists']?'✓':Text::_('COM_GENESISPRODUCTUPDATER_FILE_MISSING'); ?></td><td><?php echo (int)$item->id; ?></td></tr><?php endforeach; ?></tbody></table><?php echo $this->pagination->getListFooter(); ?><?php endif; ?><input type="hidden" name="task" value=""><input type="hidden" name="boxchecked" value="0"><?php echo HTMLHelper::_('form.token'); ?></div></form>
